/**
 * Get mock users
 */
export const getMockUsers = (): User[] => {
  return mockUsers;
};

/**
 * Get mock user by ID
 */
export const getMockUserById = (id: string): User | undefined => {
  return mockUsers.find((u) => u.id === id);
};

/**
 * Get mock current user (for logged-in user)
 */
export const getMockCurrentUser = (): User => {
  return mockUsers[0]; // Return Đinh Bộ Lĩnh as default logged-in user
};
