import React from 'react';
import { Task, TaskPriority } from '../../models/Task';
import { Badge } from '../common/Badge';
import { Button } from '../common/Button';
import { SLABadge } from '../common/SLABadge';
import { format } from 'date-fns';
import { vi } from 'date-fns/locale';
import styles from './ClaimTaskModal.module.css';

interface ClaimTaskModalProps {
  task: Task;
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  loading?: boolean;
}

const ClaimTaskModal: React.FC<ClaimTaskModalProps> = ({
  task,
  isOpen,
  onClose,
  onConfirm,
  loading = false,
}) => {
  if (!isOpen) return null;

  const getPriorityBadgeVariant = (priority: TaskPriority) => {
    switch (priority) {
      case TaskPriority.Critical:
        return 'danger';
      case TaskPriority.High:
        return 'warning';
      case TaskPriority.Medium:
        return 'info';
      case TaskPriority.Low:
        return 'success';
    }
  };

  const getPriorityLabel = (priority: TaskPriority) => {
    switch (priority) {
      case TaskPriority.Critical:
        return 'Khẩn cấp';
      case TaskPriority.High:
        return 'Cao';
      case TaskPriority.Medium:
        return 'Trung bình';
      case TaskPriority.Low:
        return 'Thấp';
    }
  };

  const getSLAStatus = (slaRemaining?: number) => {
    if (!slaRemaining) return 'safe';
    if (slaRemaining < 60) return 'danger';
    if (slaRemaining < 240) return 'warning';
    return 'safe';
  };

  const formatSLATime = (minutes?: number): string => {
    if (!minutes) return 'N/A';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    if (hours > 24) {
      const days = Math.floor(hours / 24);
      return `${days} ngày`;
    }
    if (hours > 0) return `${hours}h ${mins}m`;
    return `${mins}m`;
  };

  return (
    <>
      <div className={styles.overlay} onClick={onClose} />
      <div className={styles.modal}>
        <div className={styles.modalHeader}>
          <div>
            <h2 className={styles.modalTitle}>
              <i className="fas fa-hand-paper"></i> Xác nhận nhận công việc
            </h2>
            <p className={styles.modalSubtitle}>
              Vui lòng xem xét kỹ thông tin trước khi nhận task này
            </p>
          </div>
          <button className={styles.closeButton} onClick={onClose} disabled={loading}>
            <i className="fas fa-times"></i>
          </button>
        </div>

        <div className={styles.modalBody}>
          {/* Task Info */}
          <div className={styles.taskHeader}>
            <div>
              <div className={styles.taskId}>{task.ticketNumber || task.id}</div>
              <h3 className={styles.taskTitle}>{task.title}</h3>
            </div>
            <Badge variant={getPriorityBadgeVariant(task.priority)}>
              <i className="fas fa-exclamation-circle"></i> {getPriorityLabel(task.priority)}
            </Badge>
          </div>

          <p className={styles.taskDescription}>{task.description}</p>

          {/* Skills Required */}
          {task.skillsRequired && task.skillsRequired.length > 0 && (
            <div className={styles.section}>
              <h4 className={styles.sectionTitle}>
                <i className="fas fa-tools"></i> Kỹ năng yêu cầu
              </h4>
              <div className={styles.skillsBadges}>
                {task.skillsRequired.map((skill: string, index: number) => (
                  <Badge key={index} variant="primary">
                    {skill}
                  </Badge>
                ))}
              </div>
            </div>
          )}

          {/* Task Details Grid */}
          <div className={styles.section}>
            <h4 className={styles.sectionTitle}>
              <i className="fas fa-info-circle"></i> Chi tiết công việc
            </h4>
            <div className={styles.detailsGrid}>
              <div className={styles.detailItem}>
                <div className={styles.detailLabel}>Ước tính thời gian</div>
                <div className={styles.detailValue}>
                  <i className="fas fa-hourglass-half"></i> {task.estimatedHours} giờ
                </div>
              </div>
              <div className={styles.detailItem}>
                <div className={styles.detailLabel}>Hạn chót</div>
                <div className={styles.detailValue}>
                  <i className="fas fa-calendar"></i>{' '}
                  {format(new Date(task.dueDate), 'dd/MM/yyyy HH:mm', { locale: vi })}
                </div>
              </div>
              <div className={styles.detailItem}>
                <div className={styles.detailLabel}>Trạng thái SLA</div>
                <SLABadge
                  status={getSLAStatus(task.slaRemaining)}
                  timeRemaining={formatSLATime(task.slaRemaining)}
                />
              </div>
              <div className={styles.detailItem}>
                <div className={styles.detailLabel}>Người tạo</div>
                <div className={styles.detailValue}>
                  <i className="fas fa-user"></i> {task.creatorName}
                </div>
              </div>
            </div>
          </div>

          {/* Category and Department */}
          {(task.category || task.departmentName) && (
            <div className={styles.section}>
              <h4 className={styles.sectionTitle}>
                <i className="fas fa-layer-group"></i> Phân loại
              </h4>
              <div className={styles.badgesRow}>
                {task.category && (
                  <Badge variant="info">
                    <i className="fas fa-folder"></i> {task.category}
                  </Badge>
                )}
                {task.departmentName && (
                  <Badge variant="secondary">
                    <i className="fas fa-building"></i> {task.departmentName}
                  </Badge>
                )}
              </div>
            </div>
          )}

          {/* Warning Box */}
          <div className={styles.warningBox}>
            <div className={styles.warningIcon}>
              <i className="fas fa-exclamation-triangle"></i>
            </div>
            <div className={styles.warningContent}>
              <strong>Lưu ý quan trọng:</strong>
              <ul>
                <li>Sau khi nhận task, bạn sẽ chịu trách nhiệm hoàn thành đúng hạn</li>
                <li>Task sẽ được gán cho bạn và không thể hoàn tác</li>
                <li>Nếu gặp khó khăn, vui lòng báo cáo manager sớm nhất</li>
              </ul>
            </div>
          </div>
        </div>

        <div className={styles.modalFooter}>
          <Button variant="secondary" onClick={onClose} disabled={loading}>
            <i className="fas fa-times"></i> Hủy bỏ
          </Button>
          <Button
            variant={task.priority === TaskPriority.Critical ? 'danger' : 'primary'}
            onClick={onConfirm}
            disabled={loading}
          >
            {loading ? (
              <>
                <i className="fas fa-spinner fa-spin"></i> Đang xử lý...
              </>
            ) : (
              <>
                <i className="fas fa-check"></i> Xác nhận nhận task
              </>
            )}
          </Button>
        </div>
      </div>
    </>
  );
};

export default ClaimTaskModal;
