import React, { useState } from 'react';
import { Modal } from '../../../components/common/Modal';
import { Button } from '../../../components/common/Button';
import { TextArea } from '../../../components/common/TextArea';
import styles from './WorkflowModal.module.css';

interface RequestChangesModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (changes: string) => Promise<void>;
  taskTitle: string;
}

export const RequestChangesModal: React.FC<RequestChangesModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
  taskTitle,
}) => {
  const [changes, setChanges] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!changes.trim()) return;

    setSubmitting(true);
    try {
      await onSubmit(changes.trim());
      handleClose();
    } catch (error) {
      console.error('Failed to request changes:', error);
    } finally {
      setSubmitting(false);
    }
  };

  const handleClose = () => {
    setChanges('');
    onClose();
  };

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title="Yêu cầu chỉnh sửa" size="md">
      <form onSubmit={handleSubmit} className={styles.form}>
        <div className={styles.taskInfo}>
          <span className={styles.label}>Task:</span>
          <span className={styles.value}>{taskTitle}</span>
        </div>

        <div className={styles.warningAlert}>
          <i className="fas fa-exclamation-circle"></i>
          <span>Task sẽ được trả lại cho nhân viên để chỉnh sửa</span>
        </div>

        <div className={styles.formGroup}>
          <label htmlFor="changes" className={styles.label}>
            Nội dung cần chỉnh sửa <span className={styles.required}>*</span>
          </label>
          <TextArea
            id="changes"
            value={changes}
            onChange={(e) => setChanges(e.target.value)}
            placeholder="Ví dụ: Vui lòng kiểm tra lại phần X, cần bổ sung Y, format lại theo chuẩn Z..."
            rows={5}
            required
            disabled={submitting}
          />
          <span className={styles.hint}>
            Mô tả chi tiết những gì cần chỉnh sửa để nhân viên có thể thực hiện đúng
          </span>
        </div>

        <div className={styles.actions}>
          <Button type="button" variant="secondary" onClick={handleClose} disabled={submitting}>
            Hủy
          </Button>
          <Button type="submit" variant="warning" disabled={!changes.trim() || submitting}>
            {submitting ? 'Đang gửi...' : 'Gửi yêu cầu'}
          </Button>
        </div>
      </form>
    </Modal>
  );
};
