import { useMemo } from 'react';
import { Ticket, TicketStatus } from '../models/Ticket';
import { User, UserRole } from '../models/User';

export interface TicketPermissions {
  canView: boolean;          // Always true for authenticated users
  canEdit: boolean;          // Owner OR Admin/Manager, NOT closed/rejected
  canAssign: boolean;        // Manager/Admin, status === Triaged/Assigned/InProgress
  canTriage: boolean;        // Manager/Admin, status === Submitted/Pending
  canResolve: boolean;       // Assignee OR Admin/Manager, status === InProgress/Assigned
  canClose: boolean;         // Manager/Admin, status === Resolved/Approved
  canRequestHelp: boolean;   // Assignee, status === InProgress
  canAssignHelper: boolean;  // Manager/Admin, status === HelpRequested
  canReopen: boolean;        // Manager/Admin/Owner, status === Closed
  isOwner: boolean;          // currentUser.id === ticket.createdById
  isAssignee: boolean;       // currentUser.id === ticket.assigneeId
  isManager: boolean;        // role === Manager/Admin
}

/**
 * Custom hook to calculate ticket permissions based on user role, 
 * ticket ownership, and ticket status (workflow-based rules)
 * 
 * @param ticket - The ticket to check permissions for
 * @param currentUser - The currently authenticated user
 * @returns Object with permission flags for all ticket actions
 */
export function useTicketPermissions(
  ticket: Ticket | null,
  currentUser: User | null
): TicketPermissions {
  return useMemo(() => {
    // Default: no permissions if no ticket or no user
    if (!ticket || !currentUser) {
      return {
        canView: false,
        canEdit: false,
        canAssign: false,
        canTriage: false,
        canResolve: false,
        canClose: false,
        canRequestHelp: false,
        canAssignHelper: false,
        canReopen: false,
        isOwner: false,
        isAssignee: false,
        isManager: false,
      };
    }

    // User identity checks
    const isOwner = ticket.createdById === currentUser.id;
    const isAssignee = ticket.assigneeId === currentUser.id;
    const isManager = 
      currentUser.role === UserRole.Manager || 
      currentUser.role === UserRole.Admin;

    // Permission calculations based on workflow rules

    // Rule 1: Everyone can view
    const canView = true;

    // Rule 2: Edit permission - Owner OR Manager/Admin, NOT closed/rejected
    const canEdit = 
      ticket.status !== TicketStatus.Closed &&
      ticket.status !== TicketStatus.Rejected &&
      (isOwner || isManager);

    // Rule 3: Triage permission - Manager/Admin, status === Submitted/Pending
    const canTriage = 
      isManager &&
      (ticket.status === TicketStatus.Submitted || 
       ticket.status === TicketStatus.Pending);

    // Rule 4: Assign permission - Manager/Admin, status === Triaged (approved)/Assigned/InProgress
    // Note: "Triaged" status represents "Approved" in the workflow
    const canAssign = 
      isManager &&
      (ticket.status === TicketStatus.Triaged || 
       ticket.status === TicketStatus.Assigned || 
       ticket.status === TicketStatus.InProgress);

    // Rule 5: Resolve permission - Assignee OR Manager/Admin, status === InProgress/Assigned
    const canResolve = 
      (isAssignee || isManager) &&
      (ticket.status === TicketStatus.InProgress || 
       ticket.status === TicketStatus.Assigned);

    // Rule 6: Close permission - Manager/Admin, status === Resolved/Approved
    const canClose = 
      isManager &&
      (ticket.status === TicketStatus.Resolved || 
       ticket.status === TicketStatus.Approved);

    // Rule 7: Request Help permission - Assignee, status === InProgress
    const canRequestHelp = 
      isAssignee &&
      ticket.status === TicketStatus.InProgress;

    // Rule 8: Assign Helper permission - Manager/Admin, status === HelpRequested
    const canAssignHelper = 
      isManager &&
      ticket.status === TicketStatus.HelpRequested;

    // Rule 9: Reopen permission - Owner OR Manager/Admin, status === Closed
    const canReopen = 
      (isOwner || isManager) &&
      ticket.status === TicketStatus.Closed;

    return {
      canView,
      canEdit,
      canAssign,
      canTriage,
      canResolve,
      canClose,
      canRequestHelp,
      canAssignHelper,
      canReopen,
      isOwner,
      isAssignee,
      isManager,
    };
  }, [ticket, currentUser]);
}
