import React, { useState } from 'react';
import { Modal } from '../../../components/common/Modal';
import { Button } from '../../../components/common/Button';
import { TextArea } from '../../../components/common/TextArea';
import { Input } from '../../../components/common/Input';
import { UUID } from '../../../models/common';
import styles from './WorkflowModal.module.css';

interface RequestSupportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (request: {
    description: string;
    reason: string;
    suggestedCollaborators: UUID[];
    effortPercentage: number;
  }) => Promise<void>;
  taskId: UUID;
  taskTitle: string;
}

export const RequestSupportModal: React.FC<RequestSupportModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
  taskId: _taskId,
  taskTitle,
}) => {
  const [description, setDescription] = useState('');
  const [reason, setReason] = useState('');
  const [effortPercentage, setEffortPercentage] = useState(30);
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!description.trim() || !reason.trim()) return;

    setSubmitting(true);
    try {
      await onSubmit({
        description: description.trim(),
        reason: reason.trim(),
        suggestedCollaborators: [],
        effortPercentage,
      });
      handleClose();
    } catch (error) {
      console.error('Failed to request support:', error);
    } finally {
      setSubmitting(false);
    }
  };

  const handleClose = () => {
    setDescription('');
    setReason('');
    setEffortPercentage(30);
    onClose();
  };

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title="Yêu cầu hỗ trợ" size="md">
      <form onSubmit={handleSubmit} className={styles.form}>
        <div className={styles.taskInfo}>
          <span className={styles.label}>Task:</span>
          <span className={styles.value}>{taskTitle}</span>
        </div>

        <div className={styles.alert}>
          <i className="fas fa-info-circle"></i>
          <span>Yêu cầu hỗ trợ sẽ được gửi đến Manager/Lead để chỉ định collaborator</span>
        </div>

        <div className={styles.formGroup}>
          <label htmlFor="description" className={styles.label}>
            Mô tả công việc cần hỗ trợ <span className={styles.required}>*</span>
          </label>
          <TextArea
            id="description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Mô tả chi tiết phần việc cần collaborator hỗ trợ..."
            rows={4}
            required
            disabled={submitting}
          />
        </div>

        <div className={styles.formGroup}>
          <label htmlFor="reason" className={styles.label}>
            Lý do cần hỗ trợ <span className={styles.required}>*</span>
          </label>
          <TextArea
            id="reason"
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder="Ví dụ: Công việc phức tạp hơn dự kiến, cần chuyên môn về X, deadline gấp..."
            rows={3}
            required
            disabled={submitting}
          />
        </div>

        <div className={styles.formGroup}>
          <label htmlFor="effort" className={styles.label}>
            Ước tính effort % cho collaborator
          </label>
          <div className={styles.effortGroup}>
            <Input
              type="number"
              id="effort"
              value={effortPercentage.toString()}
              onChange={(e) => setEffortPercentage(parseInt(e.target.value) || 0)}
              min={10}
              max={50}
              step={5}
              disabled={submitting}
              className={styles.effortInput}
            />
            <span className={styles.effortLabel}>%</span>
          </div>
          <span className={styles.hint}>Tỷ lệ công việc collaborator sẽ đảm nhận (10-50%)</span>
        </div>

        <div className={styles.actions}>
          <Button type="button" variant="secondary" onClick={handleClose} disabled={submitting}>
            Hủy
          </Button>
          <Button
            type="submit"
            variant="primary"
            disabled={!description.trim() || !reason.trim() || submitting}
          >
            {submitting ? 'Đang gửi...' : 'Gửi yêu cầu'}
          </Button>
        </div>
      </form>
    </Modal>
  );
};
