import React from 'react';
import { format } from 'date-fns';
import { Task } from '../../../../models/Task';
import { getAssignmentStrategyBadge } from '../../utils/badgeHelpers';
import { getInitials } from '../../utils/formatters';
import styles from './DetailsCard.module.css';

interface DetailsCardProps {
  task: Task;
}

export const DetailsCard: React.FC<DetailsCardProps> = ({ task }) => {
  const formatDate = (date: Date | string) => {
    try {
      return format(new Date(date), 'dd/MM/yyyy HH:mm');
    } catch {
      return 'N/A';
    }
  };

  return (
    <div className={styles.detailsCard}>
      <div className={styles.cardHeader}>
        <h3 className={styles.cardTitle}>Details</h3>
      </div>
      <div className={styles.cardBody}>
        {/* Assignment Strategy */}
        <div className={styles.detailItem}>
          <div className={styles.detailLabel}>Loại giao việc</div>
          <div className={styles.detailValue}>
            {getAssignmentStrategyBadge(task.assignmentStrategy)}
          </div>
        </div>

        <div className={styles.divider} />

        {/* Creator */}
        <div className={styles.detailItem}>
          <div className={styles.detailLabel}>Người tạo</div>
          <div className={styles.detailValue}>
            <div className={styles.userInfo}>
              <div className={styles.avatar}>
                {getInitials(task.creatorName)}
              </div>
              <span>{task.creatorName}</span>
            </div>
          </div>
        </div>

        {/* Assignee */}
        <div className={styles.detailItem}>
          <div className={styles.detailLabel}>Người thực hiện</div>
          <div className={styles.detailValue}>
            {task.assigneeName ? (
              <div className={styles.userInfo}>
                <div className={styles.avatar}>
                  {getInitials(task.assigneeName)}
                </div>
                <span>{task.assigneeName}</span>
              </div>
            ) : (
              <span className={styles.notAssigned}>Chưa giao</span>
            )}
          </div>
        </div>

        <div className={styles.divider} />

        {/* Dates */}
        <div className={styles.detailItem}>
          <div className={styles.detailLabel}>Ngày tạo</div>
          <div className={styles.detailValue}>
            <i className="far fa-calendar-plus"></i>
            {formatDate(task.createdAt)}
          </div>
        </div>

        <div className={styles.detailItem}>
          <div className={styles.detailLabel}>Cập nhật</div>
          <div className={styles.detailValue}>
            <i className="far fa-calendar-check"></i>
            {formatDate(task.updatedAt)}
          </div>
        </div>

        <div className={styles.detailItem}>
          <div className={styles.detailLabel}>Deadline</div>
          <div className={styles.detailValue}>
            <i className="far fa-calendar-times"></i>
            {formatDate(task.dueDate)}
          </div>
        </div>

        <div className={styles.divider} />

        {/* Hours */}
        <div className={styles.detailItem}>
          <div className={styles.detailLabel}>Ước tính</div>
          <div className={styles.detailValue}>
            <i className="far fa-clock"></i>
            {task.estimatedHours}h
          </div>
        </div>

        <div className={styles.detailItem}>
          <div className={styles.detailLabel}>Thực tế</div>
          <div className={styles.detailValue}>
            <i className="fas fa-clock"></i>
            {task.actualHours}h
          </div>
        </div>
      </div>
    </div>
  );
};
