import React, { useState, useRef } from 'react';
import { UUID } from '../../../models/common';
import { Button } from '../../common/Button';
import { formatDistanceToNow } from 'date-fns';
import { vi } from 'date-fns/locale';
import styles from './AttachmentsTab.module.css';

export interface Attachment {
  id: UUID;
  entityId: UUID; // Can be ticketId or taskId
  fileName: string;
  fileSize: number;
  fileType: string;
  uploadedBy: string;
  uploadedAt: string;
  url: string;
}

export interface AttachmentsTabProps {
  entityId: UUID;
  entityType: 'ticket' | 'task';
  attachments?: Attachment[];
  onUpload?: (files: FileList) => Promise<void>;
  onDownload?: (attachmentId: UUID) => Promise<void>;
  onDelete?: (attachmentId: UUID) => Promise<void>;
}

export const AttachmentsTab: React.FC<AttachmentsTabProps> = ({
  entityId: _entityId,
  entityType: _entityType,
  attachments = [],
  onUpload,
  onDownload,
  onDelete,
}) => {
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setUploading(true);
    try {
      if (onUpload) {
        await onUpload(files);
      }
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    } catch (error) {
      console.error('Failed to upload files:', error);
    } finally {
      setUploading(false);
    }
  };

  const handleDownload = async (attachment: Attachment) => {
    try {
      if (onDownload) {
        await onDownload(attachment.id);
      } else {
        // Default download behavior
        window.open(attachment.url, '_blank');
      }
    } catch (error) {
      console.error('Failed to download file:', error);
    }
  };

  const handleDelete = async (attachmentId: UUID) => {
    if (!confirm('Bạn có chắc muốn xóa file này?')) return;

    try {
      if (onDelete) {
        await onDelete(attachmentId);
      }
    } catch (error) {
      console.error('Failed to delete attachment:', error);
    }
  };

  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i];
  };

  const formatTimeAgo = (dateString: string) => {
    return formatDistanceToNow(new Date(dateString), { addSuffix: true, locale: vi });
  };

  const getFileIcon = (fileType: string): string => {
    if (fileType.startsWith('image/')) return 'fa-file-image';
    if (fileType.includes('pdf')) return 'fa-file-pdf';
    if (fileType.includes('word') || fileType.includes('document')) return 'fa-file-word';
    if (fileType.includes('excel') || fileType.includes('spreadsheet')) return 'fa-file-excel';
    if (fileType.includes('powerpoint') || fileType.includes('presentation'))
      return 'fa-file-powerpoint';
    if (fileType.includes('zip') || fileType.includes('compressed')) return 'fa-file-archive';
    if (fileType.includes('video')) return 'fa-file-video';
    if (fileType.includes('audio')) return 'fa-file-audio';
    if (fileType.includes('figma')) return 'fa-pen-ruler';
    return 'fa-file';
  };

  const getFileColor = (fileType: string): string => {
    if (fileType.startsWith('image/')) return '#10b981';
    if (fileType.includes('pdf')) return '#ef4444';
    if (fileType.includes('word') || fileType.includes('document')) return '#3b82f6';
    if (fileType.includes('excel') || fileType.includes('spreadsheet')) return '#10b981';
    if (fileType.includes('powerpoint') || fileType.includes('presentation')) return '#f59e0b';
    if (fileType.includes('figma')) return '#8b5cf6';
    return '#6b7280';
  };

  return (
    <div className={styles.attachmentsTab}>
      {/* Upload Section */}
      <div className={styles.uploadSection}>
        <input
          ref={fileInputRef}
          type="file"
          multiple
          onChange={handleFileChange}
          style={{ display: 'none' }}
        />
        <Button onClick={handleUploadClick} disabled={uploading}>
          {uploading ? (
            <>
              <i className="fas fa-spinner fa-spin"></i> Đang tải lên...
            </>
          ) : (
            <>
              <i className="fas fa-upload"></i> Tải file lên
            </>
          )}
        </Button>
        <span className={styles.uploadHint}>
          <i className="fas fa-info-circle"></i> Hỗ trợ tất cả các loại file. Tối đa 10MB mỗi file.
        </span>
      </div>

      {/* Attachments List */}
      {attachments.length === 0 ? (
        <div className={styles.emptyState}>
          <i className="fas fa-paperclip fa-3x"></i>
          <p>Chưa có file đính kèm</p>
        </div>
      ) : (
        <div className={styles.attachmentsList}>
          {attachments.map((attachment) => (
            <div key={attachment.id} className={styles.attachment}>
              <div
                className={styles.fileIcon}
                style={{ color: getFileColor(attachment.fileType) }}
              >
                <i className={`fas ${getFileIcon(attachment.fileType)} fa-2x`}></i>
              </div>
              <div className={styles.fileInfo}>
                <div className={styles.fileName}>{attachment.fileName}</div>
                <div className={styles.fileMeta}>
                  <span>{formatFileSize(attachment.fileSize)}</span>
                  <span>•</span>
                  <span>{attachment.uploadedBy}</span>
                  <span>•</span>
                  <span>{formatTimeAgo(attachment.uploadedAt)}</span>
                </div>
              </div>
              <div className={styles.fileActions}>
                <button
                  className={styles.actionBtn}
                  onClick={() => handleDownload(attachment)}
                  title="Tải xuống"
                >
                  <i className="fas fa-download"></i>
                </button>
                <button
                  className={styles.actionBtn}
                  onClick={() => handleDelete(attachment.id)}
                  title="Xóa"
                >
                  <i className="fas fa-trash"></i>
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};
