/**
 * Badge generation helpers for Task Detail Page
 */

import { Badge } from '../../../components/common/Badge';
import { TaskPriority } from '../../../models/Task';

/**
 * Get priority badge with appropriate color
 */
export const getPriorityBadge = (priority: TaskPriority) => {
  switch (priority) {
    case TaskPriority.Critical:
      return <Badge variant="danger">Khẩn cấp</Badge>;
    case TaskPriority.High:
      return <Badge variant="warning">Cao</Badge>;
    case TaskPriority.Medium:
      return <Badge variant="info">Trung bình</Badge>;
    case TaskPriority.Low:
      return <Badge variant="success">Thấp</Badge>;
  }
};

/**
 * Get status badge with appropriate color
 */
export const getStatusBadge = (status: string) => {
  switch (status) {
    case 'created':
      return <Badge variant="secondary">Đã tạo</Badge>;
    case 'assigned':
      return <Badge variant="info">Đã giao</Badge>;
    case 'in_progress':
      return <Badge variant="primary">Đang thực hiện</Badge>;
    case 'under_review':
      return <Badge variant="warning">Xem xét</Badge>;
    case 'completed':
      return <Badge variant="success">Hoàn thành</Badge>;
    case 'support_requested':
      return <Badge variant="warning">Chờ hỗ trợ</Badge>;
    case 'collab_assigned':
      return <Badge variant="info">Đã phân công hỗ trợ</Badge>;
    default:
      return <Badge>{status}</Badge>;
  }
};

/**
 * Get assignment strategy badge
 */
export const getAssignmentStrategyBadge = (strategy: string) => {
  switch (strategy) {
    case 'direct':
      return <Badge variant="info">Chỉ định người</Badge>;
    case 'pool':
      return <Badge variant="secondary">Pool/Chờ nhận</Badge>;
    case 'team':
      return <Badge variant="success">Phòng ban</Badge>;
    default:
      return <Badge>{strategy}</Badge>;
  }
};

/**
 * Determine SLA status based on remaining time
 */
export const getSLAStatus = (slaRemaining?: number): 'safe' | 'warning' | 'danger' => {
  if (!slaRemaining) return 'safe';
  if (slaRemaining < 60) return 'danger';
  if (slaRemaining < 240) return 'warning';
  return 'safe';
};
