import React from 'react';
import { Ticket } from '../../../../models/Ticket';
import { SLABadge, formatSLATime, getSLAStatus } from '../../../../components/common/SLABadge';
import { TicketActions } from '../../../../components/tickets/TicketActions';
import styles from './TicketTable.module.css';

export interface TicketTableRowProps {
  ticket: Ticket;
  onView: (ticket: Ticket) => void;
  onEdit: (ticket: Ticket) => void;
  onAssign: (ticket: Ticket) => void;
  onTriage: (ticket: Ticket) => void;
}

export const TicketTableRow: React.FC<TicketTableRowProps> = ({
  ticket,
  onView,
  onEdit,
  onAssign,
  onTriage,
}) => {
  const getPriorityIcon = (priority: string) => {
    switch (priority.toLowerCase()) {
      case 'emergency':
        return 'fa-bolt';
      case 'high':
        return 'fa-arrow-up';
      case 'medium':
        return 'fa-equals';
      case 'low':
        return 'fa-arrow-down';
      default:
        return 'fa-circle';
    }
  };

  const getPriorityLabel = (priority: string) => {
    switch (priority.toLowerCase()) {
      case 'emergency':
        return 'Khẩn cấp';
      case 'high':
        return 'Cao';
      case 'medium':
        return 'Trung bình';
      case 'low':
        return 'Thấp';
      default:
        return priority;
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status.toLowerCase()) {
      case 'new':
        return 'Mới';
      case 'in_progress':
        return 'Đang xử lý';
      case 'resolved':
        return 'Đã giải quyết';
      case 'closed':
        return 'Đã đóng';
      default:
        return status;
    }
  };

  const slaStatus = getSLAStatus(ticket.sla.percentage, ticket.sla.breached);
  const slaTime = formatSLATime(ticket.sla.remainingMinutes);

  return (
    <tr className={styles.row} onClick={() => onView(ticket)}>
      <td className={styles.cell}>
        <span className={styles.code}>{ticket.id}</span>
      </td>
      <td className={styles.cell}>
        <span className={styles.title}>{ticket.title}</span>
      </td>
      <td className={styles.cell}>
        <span className={styles.department}>{ticket.departmentName}</span>
      </td>
      <td className={styles.cell}>
        <span className={`${styles.priority} ${styles[`priority-${ticket.priority.toLowerCase()}`]}`}>
          <i className={`fas ${getPriorityIcon(ticket.priority)}`}></i>
          {getPriorityLabel(ticket.priority)}
        </span>
      </td>
      <td className={styles.cell}>
        <SLABadge status={slaStatus} timeRemaining={slaTime} />
      </td>
      <td className={styles.cell}>
        {ticket.assigneeId ? (
          <div className={styles.assignee}>
            <span className={styles.avatar}>
              {ticket.assigneeName?.charAt(0).toUpperCase()}
            </span>
            <span className={styles.assigneeName}>{ticket.assigneeName}</span>
          </div>
        ) : (
          <span className={styles.unassigned}>Chưa gán</span>
        )}
      </td>
      <td className={styles.cell}>
        <span className={`${styles.status} ${styles[`status-${ticket.status.toLowerCase()}`]}`}>
          {getStatusLabel(ticket.status)}
        </span>
      </td>
      <td className={styles.cell}>
        <div onClick={(e) => e.stopPropagation()}>
          <TicketActions
            ticket={ticket}
            variant="list"
            size="sm"
            showLabels={false}
            onView={onView}
            onEdit={onEdit}
            onAssign={onAssign}
            onTriage={onTriage}
          />
        </div>
      </td>
    </tr>
  );
};
