import React, { useState } from 'react';
import { Ticket } from '../../../../models/Ticket';
import { Modal } from '../../../../components/common/Modal/Modal';
import styles from './RequestHelpModal.module.css';

interface RequestHelpModalProps {
  ticket: Ticket;
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (description: string) => Promise<void>;
}

const RequestHelpModal: React.FC<RequestHelpModalProps> = ({
  ticket,
  isOpen,
  onClose,
  onSubmit,
}) => {
  const [description, setDescription] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!description.trim()) {
      setError('Vui lòng mô tả vấn đề cần hỗ trợ');
      return;
    }

    try {
      setIsLoading(true);
      setError(null);
      await onSubmit(description.trim());
      
      // Reset form on success
      setDescription('');
      onClose();
    } catch (err) {
      setError('Có lỗi xảy ra. Vui lòng thử lại.');
      console.error('Error requesting help:', err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleClose = () => {
    if (!isLoading) {
      setDescription('');
      setError(null);
      onClose();
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={handleClose}
      title="Yêu Cầu Hỗ Trợ"
      size="md"
    >
      <form onSubmit={handleSubmit} className={styles.form}>
        <div className={styles.ticketInfo}>
          <div className={styles.infoRow}>
            <span className={styles.label}>Ticket:</span>
            <span className={styles.value}>{ticket.ticketNumber || ticket.id}</span>
          </div>
          <div className={styles.infoRow}>
            <span className={styles.label}>Tiêu đề:</span>
            <span className={styles.value}>{ticket.title}</span>
          </div>
          <div className={styles.infoRow}>
            <span className={styles.label}>Được giao cho:</span>
            <span className={styles.value}>{ticket.assigneeName || 'Chưa giao'}</span>
          </div>
        </div>

        <div className={styles.formGroup}>
          <label htmlFor="helpDescription" className={styles.labelRequired}>
            Mô tả vấn đề cần hỗ trợ
          </label>
          <textarea
            id="helpDescription"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            className={styles.textarea}
            rows={5}
            placeholder="Mô tả chi tiết vấn đề bạn đang gặp phải và cần hỗ trợ từ đồng nghiệp..."
            disabled={isLoading}
            required
          />
          <div className={styles.hint}>
            Hãy mô tả cụ thể vấn đề và loại hỗ trợ bạn cần. Manager sẽ chỉ định người hỗ trợ phù hợp.
          </div>
        </div>

        {error && (
          <div className={styles.error}>
            <i className="fas fa-exclamation-circle"></i>
            {error}
          </div>
        )}

        <div className={styles.actions}>
          <button
            type="button"
            onClick={handleClose}
            className={styles.btnSecondary}
            disabled={isLoading}
          >
            Hủy
          </button>
          <button
            type="submit"
            className={styles.btnPrimary}
            disabled={isLoading || !description.trim()}
          >
            {isLoading ? (
              <>
                <i className="fas fa-spinner fa-spin"></i>
                Đang gửi...
              </>
            ) : (
              <>
                <i className="fas fa-paper-plane"></i>
                Gửi Yêu Cầu
              </>
            )}
          </button>
        </div>
      </form>
    </Modal>
  );
};

export default RequestHelpModal;
