import React, { useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useAppSelector } from '../../store/hooks';
import { CommentsTab, AttachmentsTab, ActivityTab, ChatTab } from '../../components/shared';
import styles from './TaskDetailPage.module.css';

// Custom hooks
import { useTaskDetail, useProgressUpdate, useSubtaskManager } from './hooks';

// Components
import {
  TaskHeader,
  TaskInfoCard,
  TabNavigation,
  ChecklistTab,
  SLACard,
  ProgressCard,
  DetailsCard,
  RelatedTasksCard,
  TaskActions,
} from './components';

// Utils & Types
import { TabType, getMockChatMessages, getMockComments, getSLAStatus } from './utils';

/**
 * Task Detail Page - Displays complete task information with tabs
 * Refactored into modular components for better maintainability
 */
const TaskDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<TabType>('checklist');
  
  // Get current authenticated user
  const currentUser = useAppSelector((state) => state.auth.user);

  // Custom hooks for data and logic
  const { task, loading } = useTaskDetail(id);
  const { progress, setProgress, handleUpdateProgress, handleSubmitForReview, isUpdating } =
    useProgressUpdate(task);
  const subtaskManager = useSubtaskManager({
    taskId: id || '',
    subtasks: task?.subtasks || [],
  });

  // Mock data (TODO: Move to API/Redux when backend ready)
  const mockChatMessages = id ? getMockChatMessages(id) : [];
  const mockComments = id ? getMockComments(id) : [];

  // Loading state
  if (loading || !task) {
    return (
      <div className={styles.loading}>
        <i className="fas fa-spinner fa-spin"></i> Đang tải...
      </div>
    );
  }

  return (
    <div className={styles.taskDetailPage}>
      {/* Header Section */}
      <TaskHeader
        task={task}
        onBack={() => navigate('/tasks')}
        onSubmitForReview={
          task.status === 'in_progress' && task.progress >= 90
            ? handleSubmitForReview
            : undefined
        }
      />

      {/* Two-Column Layout */}
      <div className={styles.twoColumnLayout}>
        {/* Main Column */}
        <div className={styles.mainColumn}>
          {/* Task Information */}
          <TaskInfoCard task={task} />

          {/* Tabs Section */}
          <div className={styles.card}>
            <div
              className={styles.cardHeader}
              style={{ borderBottom: '1px solid var(--border-color)', paddingBottom: 0 }}
            >
              <TabNavigation
                activeTab={activeTab}
                onTabChange={setActiveTab}
                commentCount={mockComments.length}
                messageCount={mockChatMessages.length}
              />
            </div>

            <div className={styles.tabContent}>
              {activeTab === 'checklist' && (
                <ChecklistTab
                  task={task}
                  editingSubtasks={subtaskManager.editingSubtasks}
                  newSubtaskTitle={subtaskManager.newSubtaskTitle}
                  onToggleSubtask={subtaskManager.handleToggleSubtask}
                  onAddSubtask={subtaskManager.handleAddSubtask}
                  onDeleteSubtask={subtaskManager.handleDeleteSubtask}
                  onStartEdit={subtaskManager.handleStartEditSubtask}
                  onCancelEdit={subtaskManager.handleCancelEditSubtask}
                  onSaveEdit={subtaskManager.handleSaveEditSubtask}
                  onEditTitleChange={subtaskManager.handleEditTitleChange}
                  onNewSubtaskChange={subtaskManager.setNewSubtaskTitle}
                  isProcessing={subtaskManager.isProcessing}
                />
              )}

              {activeTab === 'chat' && (
                <ChatTab
                  entityId={id!}
                  entityType="task"
                  messages={mockChatMessages}
                  onSendMessage={async (message) => {
                    console.log('Send chat message:', message);
                    // TODO: Call API to send message
                  }}
                />
              )}

              {activeTab === 'comments' && (
                <CommentsTab
                  entityId={id!}
                  entityType="task"
                  comments={mockComments}
                  onAddComment={async (content) => {
                    console.log('Add comment:', content);
                    // TODO: Call API to add comment
                  }}
                />
              )}

              {activeTab === 'attachments' && (
                <AttachmentsTab
                  entityId={id!}
                  entityType="task"
                  attachments={[]} // TODO: Load from API
                  onUpload={async (files) => {
                    console.log('Upload files:', files);
                    // TODO: Call API to upload
                  }}
                />
              )}

              {activeTab === 'activity' && (
                <ActivityTab
                  entityId={id!}
                  entityType="task"
                  activities={[]} // TODO: Load from API
                />
              )}
            </div>
          </div>
        </div>

        {/* Right Sidebar */}
        <div className={styles.rightSidebar}>
          {/* Task Actions */}
          {currentUser && (
            <TaskActions
              task={task}
              currentUser={currentUser}
            />
          )}

          {/* SLA Card (conditional) */}
          {task.slaRemaining && task.status !== 'completed' && (
            <SLACard
              slaRemaining={task.slaRemaining}
              status={getSLAStatus(task.slaRemaining)}
            />
          )}

          {/* Progress Card (conditional) */}
          {task.status !== 'completed' && (
            <ProgressCard
              progress={progress}
              onProgressChange={setProgress}
              onUpdate={handleUpdateProgress}
              isUpdating={isUpdating}
            />
          )}

          {/* Details Card */}
          <DetailsCard task={task} />

          {/* Related Tasks Card */}
          <RelatedTasksCard relatedTasks={[]} />
        </div>
      </div>
    </div>
  );
};

export default TaskDetailPage;
