import React from 'react';
import styles from './TabNavigation.module.css';

export type TabType = 'checklist' | 'chat' | 'comments' | 'attachments' | 'activity';

export interface TabNavigationProps {
  activeTab: TabType;
  onTabChange: (tab: TabType) => void;
  commentCount?: number;
  messageCount?: number;
}

interface TabConfig {
  key: TabType;
  icon: string;
  label: string;
  countKey?: 'commentCount' | 'messageCount';
}

const tabs: TabConfig[] = [
  { key: 'checklist', icon: 'fas fa-tasks', label: 'Checklist' },
  { key: 'chat', icon: 'fas fa-comments', label: 'Trao đổi', countKey: 'messageCount' },
  { key: 'comments', icon: 'fas fa-comment-dots', label: 'Bình luận', countKey: 'commentCount' },
  { key: 'attachments', icon: 'fas fa-paperclip', label: 'Files' },
  { key: 'activity', icon: 'fas fa-history', label: 'Activity' },
];

export const TabNavigation: React.FC<TabNavigationProps> = ({
  activeTab,
  onTabChange,
  commentCount,
  messageCount,
}) => {
  const getCounts = (countKey?: 'commentCount' | 'messageCount'): number | undefined => {
    if (countKey === 'commentCount') return commentCount;
    if (countKey === 'messageCount') return messageCount;
    return undefined;
  };

  return (
    <div className={styles.tabs}>
      {tabs.map((tab) => {
        const count = getCounts(tab.countKey);
        const isActive = activeTab === tab.key;

        return (
          <button
            key={tab.key}
            className={`${styles.tab} ${isActive ? styles.active : ''}`}
            onClick={() => onTabChange(tab.key)}
          >
            <i className={tab.icon}></i> {tab.label}
            {count !== undefined && count > 0 && (
              <span className={styles.badge}>{count}</span>
            )}
          </button>
        );
      })}
    </div>
  );
};
