import React from 'react';
import { Ticket } from '../../../../models/Ticket';
import { UserRole } from '../../../../models/User';
import styles from './TicketHelpersDisplay.module.css';

interface TicketHelpersDisplayProps {
  ticket: Ticket;
  currentUserRole: UserRole;
  onRemoveHelper?: (helperId: string) => void;
}

const TicketHelpersDisplay: React.FC<TicketHelpersDisplayProps> = ({
  ticket,
  currentUserRole,
  onRemoveHelper,
}) => {
  const helpers = ticket.helpers || [];
  const canRemoveHelpers = currentUserRole === UserRole.Manager || currentUserRole === UserRole.Admin;

  if (helpers.length === 0) {
    return null;
  }

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h4 className={styles.title}>
          <i className="fas fa-users"></i>
          Người Hỗ Trợ ({helpers.length})
        </h4>
      </div>

      {/* Help Request Description */}
      {ticket.helpRequestDescription && (
        <div className={styles.helpRequest}>
          <div className={styles.helpRequestLabel}>
            <i className="fas fa-comment-dots"></i>
            Yêu cầu hỗ trợ:
          </div>
          <div className={styles.helpRequestText}>
            {ticket.helpRequestDescription}
          </div>
          {ticket.helpRequestedAt && (
            <div className={styles.helpRequestTime}>
              {new Date(ticket.helpRequestedAt).toLocaleString('vi-VN', {
                year: 'numeric',
                month: '2-digit',
                day: '2-digit',
                hour: '2-digit',
                minute: '2-digit',
              })}
            </div>
          )}
        </div>
      )}

      {/* Helpers List */}
      <div className={styles.helpersList}>
        {helpers.map((helper) => (
          <div key={helper.id} className={styles.helperCard}>
            <div className={styles.helperAvatar}>
              <i className="fas fa-user-circle"></i>
            </div>
            <div className={styles.helperInfo}>
              <div className={styles.helperName}>{helper.userName}</div>
              <div className={styles.helperMeta}>
                <span>
                  <i className="fas fa-user-check"></i>
                  Chỉ định bởi {helper.assignedByName}
                </span>
                <span>
                  <i className="fas fa-clock"></i>
                  {new Date(helper.assignedAt).toLocaleDateString('vi-VN')}
                </span>
              </div>
            </div>
            {canRemoveHelpers && onRemoveHelper && (
              <button
                type="button"
                onClick={() => onRemoveHelper(helper.id)}
                className={styles.btnRemove}
                title="Xóa người hỗ trợ"
              >
                <i className="fas fa-times"></i>
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default TicketHelpersDisplay;
