import React from 'react';
import { PerformanceStats } from '../../../models/Statistics';
import { StatCard } from '../../dashboard/StatCard';
import styles from './PerformanceCards.module.css';

interface PerformanceCardsProps {
  data: PerformanceStats;
}

export const PerformanceCards: React.FC<PerformanceCardsProps> = ({ data }) => {
  return (
    <div className={styles.grid}>
      <StatCard
        icon="fas fa-tasks"
        iconVariant="primary"
        label="Tổng công việc"
        value={data.totalTasks}
        change={{
          text: `+${data.trend.tasksChange}% so với tháng trước`,
          positive: data.trend.tasksChange > 0,
        }}
      />
      <StatCard
        icon="fas fa-check-circle"
        iconVariant="success"
        label="Đã hoàn thành"
        value={data.completedTasks}
        change={{
          text: `Tỷ lệ: ${data.completionRate}%`,
        }}
      />
      <StatCard
        icon="fas fa-clock"
        iconVariant="warning"
        label="Tổng thời gian"
        value={`${data.totalTime}h`}
        change={{
          text: `TB: ${data.averageTimePerTask}h/task`,
        }}
      />
      <StatCard
        icon="fas fa-star"
        iconVariant="info"
        label="Đánh giá"
        value={data.averageRating.toFixed(1)}
        change={{
          text: `+${data.trend.ratingChange} so với tháng trước`,
          positive: data.trend.ratingChange > 0,
        }}
      />
      <StatCard
        icon="fas fa-exclamation-triangle"
        iconVariant="danger"
        label="Vi phạm SLA"
        value={data.slaViolations}
        change={{
          text: `${data.slaViolationRate.toFixed(1)}% tổng số task`,
        }}
      />
      <StatCard
        icon="fas fa-trophy"
        iconVariant="primary"
        label="Hạng"
        value={`#${data.rank}`}
        change={{
          text: `Trong ${data.totalEmployees} nhân viên`,
        }}
      />
    </div>
  );
};
