import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { AppDispatch } from '../../../../store/store';
import { Task } from '../../../../models/Task';
import { User } from '../../../../models/User';
import { Button } from '../../../../components/common/Button';
import { useToast } from '../../../../components/common/Toast';
import { useTaskPermissions } from '../../../../hooks/useTaskPermissions';
import {
  requestSupport,
  assignCollaborator,
  markBlocked,
  unblockTask,
  approveTask,
  requestChanges,
  cancelTask,
  startTask,
} from '../../../../store/slices/tasksSlice';
import { RequestSupportModal } from '../RequestSupportModal';
import AssignCollaboratorModal from '../AssignCollaboratorModal';
import { MarkBlockedModal } from '../MarkBlockedModal';
import { ApproveTaskModal } from '../ApproveTaskModal';
import { RequestChangesModal } from '../RequestChangesModal';
import { CancelTaskModal } from '../CancelTaskModal';
import styles from './TaskActions.module.css';

export interface TaskActionsProps {
  task: Task;
  currentUser: User; // Current authenticated user
}

/**
 * TaskActions Component
 * 
 * Displays available actions for a task based on:
 * - User role (Admin, Manager, Staff)
 * - Task ownership (creator)
 * - Assignee status
 * - Collaborator status
 * - Current task status (workflow-based permissions)
 * 
 * Uses useTaskPermissions hook for permission management
 */
export const TaskActions: React.FC<TaskActionsProps> = ({ task, currentUser }) => {
  const dispatch = useDispatch<AppDispatch>();
  const toast = useToast();
  const [isProcessing, setIsProcessing] = useState(false);
  
  // Get permissions from hook
  const permissions = useTaskPermissions(task, currentUser);

  // Modal states
  const [showRequestSupportModal, setShowRequestSupportModal] = useState(false);
  const [showAssignCollaboratorModal, setShowAssignCollaboratorModal] = useState(false);
  const [showMarkBlockedModal, setShowMarkBlockedModal] = useState(false);
  const [showApproveModal, setShowApproveModal] = useState(false);
  const [showRequestChangesModal, setShowRequestChangesModal] = useState(false);
  const [showCancelModal, setShowCancelModal] = useState(false);

  // Start Task
  const handleStartTask = async () => {
    if (!window.confirm('Bắt đầu làm việc với task này?')) return;

    setIsProcessing(true);
    try {
      await dispatch(startTask(task.id)).unwrap();
      toast.success('Đã bắt đầu task!');
    } catch (error) {
      toast.error('Có lỗi xảy ra: ' + error);
    } finally {
      setIsProcessing(false);
    }
  };

  // Request Support
  const handleRequestSupport = async (request: {
    description: string;
    reason: string;
    suggestedCollaborators: string[];
    effortPercentage: number;
  }) => {
    try {
      await dispatch(
        requestSupport({
          taskId: task.id,
          description: request.description,
          effortPercentage: request.effortPercentage,
        })
      ).unwrap();
      toast.success('Đã gửi yêu cầu hỗ trợ!');
    } catch (error) {
      toast.error('Có lỗi xảy ra: ' + error);
      throw error;
    }
  };

  // Assign Collaborator (Manager)
  const handleAssignCollaborator = async (
    collaborators: {
      userId: string;
      userName: string;
      role: 'support' | 'reviewer' | 'contributor';
      effortPercentage: number;
    }[]
  ) => {
    try {
      // Dispatch for each collaborator
      for (const collaborator of collaborators) {
        await dispatch(
          assignCollaborator({
            taskId: task.id,
            userId: collaborator.userId,
            userName: collaborator.userName,
            role: collaborator.role,
            effortPercentage: collaborator.effortPercentage,
          })
        ).unwrap();
      }
      toast.success(`Đã phân công ${collaborators.length} người hỗ trợ!`);
    } catch (error) {
      toast.error('Có lỗi xảy ra: ' + error);
      throw error;
    }
  };

  // Mark Blocked
  const handleMarkBlocked = async (reason: string) => {
    try {
      await dispatch(
        markBlocked({
          taskId: task.id,
          reason,
        })
      ).unwrap();
      toast.warning('Đã đánh dấu task bị block!');
    } catch (error) {
      toast.error('Có lỗi xảy ra: ' + error);
      throw error;
    }
  };

  // Unblock Task
  const handleUnblock = async () => {
    if (!window.confirm('Mở khóa task này?')) return;

    setIsProcessing(true);
    try {
      await dispatch(unblockTask(task.id)).unwrap();
      toast.success('Đã mở khóa task!');
    } catch (error) {
      toast.error('Có lỗi xảy ra: ' + error);
    } finally {
      setIsProcessing(false);
    }
  };

  // Approve Task (Manager)
  const handleApprove = async (rating: number) => {
    try {
      await dispatch(
        approveTask({
          taskId: task.id,
          rating,
        })
      ).unwrap();
      toast.success('Đã duyệt task!');
    } catch (error) {
      toast.error('Có lỗi xảy ra: ' + error);
      throw error;
    }
  };

  // Request Changes (Manager)
  const handleRequestChanges = async (changes: string) => {
    try {
      await dispatch(
        requestChanges({
          taskId: task.id,
          changes,
        })
      ).unwrap();
      toast.warning('Đã gửi yêu cầu chỉnh sửa!');
    } catch (error) {
      toast.error('Có lỗi xảy ra: ' + error);
      throw error;
    }
  };

  // Cancel Task (Manager)
  const handleCancel = async (reason: string) => {
    try {
      await dispatch(
        cancelTask({
          taskId: task.id,
          reason,
        })
      ).unwrap();
      toast.success('Đã hủy task!');
    } catch (error) {
      toast.error('Có lỗi xảy ra: ' + error);
      throw error;
    }
  };

  // Determine which actions to show based on permissions from hook
  // Uses workflow-based rules from useTaskPermissions
  
  // If no actions available, don't render anything
  const hasActions =
    permissions.canStart ||
    permissions.canRequestSupport ||
    permissions.canAssignCollaborator ||
    permissions.canMarkBlocked ||
    permissions.canUnblock ||
    permissions.canSubmitForReview ||
    permissions.canReassign ||
    permissions.canApprove ||
    permissions.canRequestChanges ||
    permissions.canCancel;

  if (!hasActions) {
    return null;
  }

  return (
    <>
      <div className={styles.taskActions}>
        <div className={styles.actionsHeader}>
          <i className="fas fa-tasks"></i>
          <h3>Hành động</h3>
        </div>
        <div className={styles.actionsButtons}>
          {/* Staff Actions */}
          {permissions.canStart && (
            <Button
              variant="primary"
              onClick={handleStartTask}
              disabled={isProcessing}
              fullWidth
            >
              <i className="fas fa-play"></i> Bắt đầu làm việc
            </Button>
          )}

          {permissions.canRequestSupport && (
            <Button
              variant="secondary"
              onClick={() => setShowRequestSupportModal(true)}
              disabled={isProcessing}
              fullWidth
            >
              <i className="fas fa-hands-helping"></i> Yêu cầu hỗ trợ
            </Button>
          )}

          {permissions.canSubmitForReview && (
            <Button
              variant="success"
              onClick={async () => {
                if (!window.confirm('Gửi task để manager review?')) return;
                setIsProcessing(true);
                try {
                  // TODO: Implement submitForReview thunk
                  toast.success('Đã gửi task để review!');
                } catch (error) {
                  toast.error('Có lỗi xảy ra: ' + error);
                } finally {
                  setIsProcessing(false);
                }
              }}
              disabled={isProcessing}
              fullWidth
            >
              <i className="fas fa-paper-plane"></i> Gửi để review
            </Button>
          )}

          {/* Manager Actions */}
          {permissions.canAssignCollaborator && (
            <Button
              variant="primary"
              onClick={() => setShowAssignCollaboratorModal(true)}
              disabled={isProcessing}
              fullWidth
            >
              <i className="fas fa-user-plus"></i> Phân công người hỗ trợ
            </Button>
          )}

          {permissions.canReassign && (
            <Button
              variant="secondary"
              onClick={async () => {
                const newAssignee = prompt('Nhập ID người được gán mới:');
                if (!newAssignee) return;
                const reason = prompt('Lý do gán lại:');
                if (!reason) return;
                setIsProcessing(true);
                try {
                  // TODO: Implement reassignTask thunk
                  toast.success('Đã gán lại task!');
                } catch (error) {
                  toast.error('Có lỗi xảy ra: ' + error);
                } finally {
                  setIsProcessing(false);
                }
              }}
              disabled={isProcessing}
              fullWidth
            >
              <i className="fas fa-exchange-alt"></i> Gán lại task
            </Button>
          )}

          {permissions.canMarkBlocked && (
            <Button
              variant="warning"
              onClick={() => setShowMarkBlockedModal(true)}
              disabled={isProcessing}
              fullWidth
            >
              <i className="fas fa-ban"></i> Đánh dấu bị block
            </Button>
          )}

          {permissions.canUnblock && (
            <Button
              variant="success"
              onClick={handleUnblock}
              disabled={isProcessing}
              fullWidth
            >
              <i className="fas fa-unlock"></i> Mở khóa task
            </Button>
          )}

          {permissions.canApprove && (
            <Button
              variant="success"
              onClick={() => setShowApproveModal(true)}
              disabled={isProcessing}
              fullWidth
            >
              <i className="fas fa-check-circle"></i> Duyệt task
            </Button>
          )}

          {permissions.canRequestChanges && (
            <Button
              variant="warning"
              onClick={() => setShowRequestChangesModal(true)}
              disabled={isProcessing}
              fullWidth
            >
              <i className="fas fa-edit"></i> Yêu cầu chỉnh sửa
            </Button>
          )}

          {permissions.canCancel && (
            <Button
              variant="danger"
              onClick={() => setShowCancelModal(true)}
              disabled={isProcessing}
              fullWidth
            >
              <i className="fas fa-times-circle"></i> Hủy task
            </Button>
          )}
        </div>
      </div>

      {/* Modals */}
      <RequestSupportModal
        isOpen={showRequestSupportModal}
        onClose={() => setShowRequestSupportModal(false)}
        onSubmit={handleRequestSupport}
        taskId={task.id}
        taskTitle={task.title}
      />

      <AssignCollaboratorModal
        isOpen={showAssignCollaboratorModal}
        onClose={() => setShowAssignCollaboratorModal(false)}
        onSubmit={handleAssignCollaborator}
        supportRequest={task.supportRequest}
        taskTitle={task.title}
      />

      <MarkBlockedModal
        isOpen={showMarkBlockedModal}
        onClose={() => setShowMarkBlockedModal(false)}
        onSubmit={handleMarkBlocked}
        taskTitle={task.title}
      />

      <ApproveTaskModal
        isOpen={showApproveModal}
        onClose={() => setShowApproveModal(false)}
        onSubmit={handleApprove}
        taskTitle={task.title}
      />

      <RequestChangesModal
        isOpen={showRequestChangesModal}
        onClose={() => setShowRequestChangesModal(false)}
        onSubmit={handleRequestChanges}
        taskTitle={task.title}
      />

      <CancelTaskModal
        isOpen={showCancelModal}
        onClose={() => setShowCancelModal(false)}
        onSubmit={handleCancel}
        taskTitle={task.title}
      />
    </>
  );
};
