import React from 'react';
import { TaskFilters as ITaskFilters, TaskPriority, TaskStatus } from '../../../models/Task';
import { Select, SelectOption } from '../../../components/common/Select';
import { Input } from '../../../components/common/Input';
import styles from './TaskFilters.module.css';

interface TaskFiltersProps {
  filters: ITaskFilters;
  onFilterChange: (filters: ITaskFilters) => void;
}

export const TaskFiltersComponent: React.FC<TaskFiltersProps> = ({
  filters,
  onFilterChange,
}) => {
  const handleChange = (key: keyof ITaskFilters, value: any) => {
    onFilterChange({ ...filters, [key]: value || undefined });
  };

  const priorityOptions: SelectOption[] = [
    { value: '', label: 'Tất cả ưu tiên' },
    { value: TaskPriority.Critical, label: 'Khẩn cấp' },
    { value: TaskPriority.High, label: 'Cao' },
    { value: TaskPriority.Medium, label: 'Trung bình' },
    { value: TaskPriority.Low, label: 'Thấp' },
  ];

  const statusOptions: SelectOption[] = [
    { value: '', label: 'Tất cả trạng thái' },
    { value: TaskStatus.Created, label: 'Đã tạo' },
    { value: TaskStatus.Assigned, label: 'Đã giao' },
    { value: TaskStatus.InProgress, label: 'Đang thực hiện' },
    { value: TaskStatus.UnderReview, label: 'Xem xét' },
    { value: TaskStatus.Completed, label: 'Hoàn thành' },
  ];

  return (
    <div className={styles.filters}>
      <Input
        placeholder="Tìm task theo ID, tiêu đề..."
        value={filters.search || ''}
        onChange={(e) => handleChange('search', e.target.value)}
        className={styles.searchInput}
      />

      <Select
        value={filters.priority || ''}
        onChange={(e) => handleChange('priority', e.target.value)}
        className={styles.filterSelect}
        options={priorityOptions}
      />

      <Select
        value={filters.status || ''}
        onChange={(e) => handleChange('status', e.target.value)}
        className={styles.filterSelect}
        options={statusOptions}
      />
    </div>
  );
};
