import React, { useState } from 'react';
import { Ticket } from '../../../models/Ticket';
import { Card } from '../../../components/common/Card';
import { ChatTab, ChatMessage } from '../../../components/shared';
import CommentsTab from './tabs/CommentsTab';
import ActivityTab from './tabs/ActivityTab';
import AttachmentsTab from './tabs/AttachmentsTab';
import styles from './TicketTabs.module.css';

interface TicketTabsProps {
  ticket: Ticket;
}

type TabType = 'chat' | 'comments' | 'activity' | 'attachments';

const TicketTabs: React.FC<TicketTabsProps> = ({ ticket }) => {
  const [activeTab, setActiveTab] = useState<TabType>('chat');

  // Mock chat messages for ticket
  const mockChatMessages: ChatMessage[] = [
    {
      id: 'chat-1',
      entityId: ticket.id,
      userId: 'user-001',
      userName: 'Linh Dinh',
      userAvatar: 'LD',
      message: 'Đã kiểm tra máy in, có thể là do hết mực hoặc bị kẹt giấy.',
      timestamp: new Date(Date.now() - 90 * 60 * 1000).toISOString(), // 1.5 hours ago
    },
    {
      id: 'chat-2',
      entityId: ticket.id,
      userId: 'user-002',
      userName: 'Nguyễn Văn A',
      userAvatar: 'NA',
      message: 'Đã mở nắp máy in, không thấy kẹt giấy. Mực còn 30%.',
      timestamp: new Date(Date.now() - 85 * 60 * 1000).toISOString(), // 1h25m ago
    },
    {
      id: 'chat-3',
      entityId: ticket.id,
      userId: 'user-001',
      userName: 'Linh Dinh',
      userAvatar: 'LD',
      message: 'OK, tôi sẽ đến kiểm tra ngay. Có thể là lỗi driver.',
      timestamp: new Date(Date.now() - 80 * 60 * 1000).toISOString(), // 1h20m ago
    },
  ];

  const renderTabContent = () => {
    switch (activeTab) {
      case 'chat':
        return (
          <ChatTab
            entityId={ticket.id}
            entityType="ticket"
            messages={mockChatMessages}
            onSendMessage={async (message) => {
              console.log('Send ticket chat message:', message);
              // TODO: Call API to send message
            }}
          />
        );
      case 'comments':
        return <CommentsTab ticketId={ticket.id} />;
      case 'activity':
        return <ActivityTab ticketId={ticket.id} />;
      case 'attachments':
        return <AttachmentsTab ticketId={ticket.id} />;
      default:
        return null;
    }
  };

  return (
    <Card>
      <div className={styles.tabsHeader}>
        <div className={styles.tabs}>
          <button
            className={`${styles.tabBtn} ${activeTab === 'chat' ? styles.active : ''}`}
            onClick={() => setActiveTab('chat')}
          >
            <i className="fas fa-comments"></i> Trao đổi
            <span className={styles.badge}>3</span>
          </button>
          <button
            className={`${styles.tabBtn} ${activeTab === 'comments' ? styles.active : ''}`}
            onClick={() => setActiveTab('comments')}
          >
            <i className="fas fa-comment-dots"></i> Bình luận
            <span className={`${styles.badge} ${styles.badgeGray}`}>{ticket.commentCount || 0}</span>
          </button>
          <button
            className={`${styles.tabBtn} ${activeTab === 'activity' ? styles.active : ''}`}
            onClick={() => setActiveTab('activity')}
          >
            <i className="fas fa-history"></i> Activity
          </button>
          <button
            className={`${styles.tabBtn} ${activeTab === 'attachments' ? styles.active : ''}`}
            onClick={() => setActiveTab('attachments')}
          >
            <i className="fas fa-paperclip"></i> Files
            <span className={`${styles.badge} ${styles.badgeGray}`}>{ticket.attachmentCount || 0}</span>
          </button>
        </div>
      </div>
      <div className={styles.tabContent}>{renderTabContent()}</div>
    </Card>
  );
};

export default TicketTabs;
