/**
 * SLAComplianceReport Component
 * Displays SLA compliance metrics and breach details
 */

import React from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  ArcElement,
  Filler,
  Tooltip,
  Legend,
} from 'chart.js';
import { Line, Doughnut } from 'react-chartjs-2';
import type { SLAComplianceMetrics } from '../../../models/Report';
import styles from './SLAComplianceReport.module.css';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  ArcElement,
  Filler,
  Tooltip,
  Legend
);

interface SLAComplianceReportProps {
  data: SLAComplianceMetrics;
}

export const SLAComplianceReport: React.FC<SLAComplianceReportProps> = ({
  data,
}) => {
  const trendChartData = {
    labels: data.trend.map((point) => point.label),
    datasets: [
      {
        label: 'SLA Compliance %',
        data: data.trend.map((point) => point.value),
        borderColor: '#10b981',
        backgroundColor: 'rgba(16, 185, 129, 0.1)',
        tension: 0.4,
        fill: true,
      },
    ],
  };

  const trendChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false,
      },
    },
    scales: {
      y: {
        beginAtZero: false,
        min: 80,
        max: 100,
      },
    },
  };

  const priorityChartData = {
    labels: ['Critical', 'High', 'Medium', 'Low'],
    datasets: [
      {
        data: [
          data.byPriority.critical,
          data.byPriority.high,
          data.byPriority.medium,
          data.byPriority.low,
        ],
        backgroundColor: ['#ef4444', '#f59e0b', '#3b82f6', '#10b981'],
      },
    ],
  };

  const priorityChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom' as const,
      },
    },
  };

  const getPriorityBadgeClass = (priority: string) => {
    switch (priority) {
      case 'critical':
        return styles.badgeCritical;
      case 'high':
        return styles.badgeHigh;
      case 'medium':
        return styles.badgeMedium;
      default:
        return styles.badgeLow;
    }
  };

  return (
    <div className={styles.container}>
      {/* Trend and Priority Charts */}
      <div className={styles.chartsGrid}>
        <div className={styles.reportCard}>
          <div className={styles.cardHeader}>
            <h3 className={styles.cardTitle}>
              <i className="fas fa-chart-area"></i>
              SLA Compliance Trend
            </h3>
            <button className={styles.exportButton}>
              <i className="fas fa-download"></i>
            </button>
          </div>
          <div className={styles.cardBody}>
            <div className={styles.chartContainer}>
              <Line data={trendChartData} options={trendChartOptions} />
            </div>
          </div>
        </div>

        <div className={styles.reportCard}>
          <div className={styles.cardHeader}>
            <h3 className={styles.cardTitle}>
              <i className="fas fa-chart-pie"></i>
              SLA by Priority
            </h3>
          </div>
          <div className={styles.cardBody}>
            <div className={styles.chartContainer}>
              <Doughnut
                data={priorityChartData}
                options={priorityChartOptions}
              />
            </div>
          </div>
        </div>
      </div>

      {/* SLA Breach Details Table */}
      <div className={styles.reportCard}>
        <div className={styles.cardHeader}>
          <h3 className={styles.cardTitle}>
            <i className="fas fa-exclamation-triangle"></i>
            SLA Breach Details
          </h3>
        </div>
        <div className={styles.cardBody}>
          <div className={styles.tableContainer}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>Ticket ID</th>
                  <th>Tiêu đề</th>
                  <th>Ưu tiên</th>
                  <th>Người xử lý</th>
                  <th>SLA Target</th>
                  <th>Actual Time</th>
                  <th>Breach Time</th>
                  <th>Trạng thái</th>
                </tr>
              </thead>
              <tbody>
                {data.breaches.map((breach) => (
                  <tr key={breach.ticketId}>
                    <td>
                      <strong>#{breach.ticketId}</strong>
                    </td>
                    <td>{breach.title}</td>
                    <td>
                      <span
                        className={`${styles.badge} ${getPriorityBadgeClass(
                          breach.priority
                        )}`}
                      >
                        {breach.priority === 'critical' && 'KHẨN CẤP'}
                        {breach.priority === 'high' && 'CAO'}
                        {breach.priority === 'medium' && 'TRUNG BÌNH'}
                        {breach.priority === 'low' && 'THẤP'}
                      </span>
                    </td>
                    <td>{breach.assignee}</td>
                    <td>{breach.slaTarget}</td>
                    <td>{breach.actualTime}</td>
                    <td className={styles.breachTime}>{breach.breachTime}</td>
                    <td>
                      <span className={styles.badgeResolved}>
                        {breach.status}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};
