import React from 'react';
import { PersonalGoal } from '../../../models/Statistics';
import styles from './GoalCard.module.css';

interface GoalCardProps {
  goal: PersonalGoal;
  onUpdate?: (goalId: string, updates: Partial<PersonalGoal>) => void;
  onDelete?: (goalId: string) => void;
}

export const GoalCard: React.FC<GoalCardProps> = ({ goal }) => {
  const getStatusColor = () => {
    switch (goal.status) {
      case 'completed':
        return 'var(--success-color)';
      case 'on-track':
        return 'var(--primary-color)';
      case 'at-risk':
        return 'var(--warning-color)';
      case 'overdue':
        return 'var(--danger-color)';
      default:
        return 'var(--gray-500)';
    }
  };

  const getStatusLabel = () => {
    switch (goal.status) {
      case 'completed':
        return 'Đã hoàn thành';
      case 'on-track':
        return 'Đúng tiến độ';
      case 'at-risk':
        return 'Có rủi ro';
      case 'overdue':
        return 'Quá hạn';
      default:
        return '';
    }
  };

  const getCategoryIcon = () => {
    switch (goal.category) {
      case 'productivity':
        return 'fas fa-chart-line';
      case 'quality':
        return 'fas fa-star';
      case 'sla':
        return 'fas fa-clock';
      case 'learning':
        return 'fas fa-graduation-cap';
      default:
        return 'fas fa-target';
    }
  };

  return (
    <div className={styles.goalCard}>
      <div className={styles.header}>
        <div className={styles.categoryIcon}>
          <i className={getCategoryIcon()}></i>
        </div>
        <div className={styles.status} style={{ color: getStatusColor() }}>
          {getStatusLabel()}
        </div>
      </div>
      <h4 className={styles.title}>{goal.title}</h4>
      <p className={styles.description}>{goal.description}</p>
      <div className={styles.progress}>
        <div className={styles.progressHeader}>
          <span className={styles.progressLabel}>
            {goal.current} / {goal.target} {goal.unit}
          </span>
          <span className={styles.progressPercentage}>{goal.progress}%</span>
        </div>
        <div className={styles.progressBar}>
          <div
            className={styles.progressFill}
            style={{
              width: `${goal.progress}%`,
              backgroundColor: getStatusColor(),
            }}
          ></div>
        </div>
      </div>
      <div className={styles.deadline}>
        <i className="fas fa-calendar"></i>
        Hạn:{' '}
        {new Date(goal.deadline).toLocaleDateString('vi-VN', {
          day: '2-digit',
          month: '2-digit',
          year: 'numeric',
        })}
      </div>
    </div>
  );
};
