import React, { useRef } from 'react';
import { UUID } from '../../../../../models/common';
import { Button } from '../../../../../components/common/Button';
import { getFileTypeFromMime, getFileIcon, formatFileSize, AttachmentFileType } from '../../../../../models/Attachment';
import styles from './AttachmentsTab.module.css';

interface AttachmentsTabProps {
  ticketId: UUID;
}

interface Attachment {
  id: string;
  fileName: string;
  fileSize: number;
  fileType: string;
  uploadedAt: Date;
}

const AttachmentsTab: React.FC<AttachmentsTabProps> = () => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Mock attachments
  const attachments: Attachment[] = [
    {
      id: '1',
      fileName: 'printer-error.jpg',
      fileSize: 245 * 1024, // 245 KB
      fileType: 'image/jpeg',
      uploadedAt: new Date('2024-03-24T08:15:00'),
    },
    {
      id: '2',
      fileName: 'manual.pdf',
      fileSize: 1.2 * 1024 * 1024, // 1.2 MB
      fileType: 'application/pdf',
      uploadedAt: new Date('2024-03-24T09:30:00'),
    },
  ];

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    // TODO: Upload files via API
    console.log('Uploading files:', files);
  };

  const handleDownload = (attachmentId: string, fileName: string) => {
    // TODO: Download file via API
    console.log('Downloading:', attachmentId, fileName);
  };

  const formatTimeAgo = (date: Date) => {
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    
    if (diffHours < 1) {
      const diffMins = Math.floor(diffMs / (1000 * 60));
      return `${diffMins} phút trước`;
    }
    if (diffHours < 24) {
      return `${diffHours} giờ trước`;
    }
    const diffDays = Math.floor(diffHours / 24);
    return `${diffDays} ngày trước`;
  };

  const getFileIconColor = (fileType: AttachmentFileType) => {
    switch (fileType) {
      case AttachmentFileType.Image:
        return 'var(--blue-500)';
      case AttachmentFileType.PDF:
        return 'var(--red-500)';
      case AttachmentFileType.Document:
        return 'var(--purple-500)';
      default:
        return 'var(--gray-500)';
    }
  };

  const getBackgroundColor = (fileType: AttachmentFileType) => {
    switch (fileType) {
      case AttachmentFileType.Image:
        return 'var(--blue-100)';
      case AttachmentFileType.PDF:
        return 'var(--red-100)';
      case AttachmentFileType.Document:
        return 'var(--purple-100)';
      default:
        return 'var(--gray-100)';
    }
  };

  return (
    <div className={styles.container}>
      <div className={styles.attachments}>
        {attachments.length === 0 ? (
          <div className={styles.empty}>
            <i className="fas fa-paperclip"></i>
            <p>Chưa có file đính kèm nào</p>
          </div>
        ) : (
          attachments.map((attachment) => {
            const fileType = getFileTypeFromMime(attachment.fileType);
            const iconClass = getFileIcon(fileType);
            const iconColor = getFileIconColor(fileType);
            const bgColor = getBackgroundColor(fileType);

            return (
              <div key={attachment.id} className={styles.attachmentItem}>
                <div 
                  className={styles.fileIcon}
                  style={{ backgroundColor: bgColor }}
                >
                  <i className={iconClass} style={{ color: iconColor }}></i>
                </div>
                <div className={styles.fileInfo}>
                  <div className={styles.fileName}>{attachment.fileName}</div>
                  <div className={styles.fileMeta}>
                    {formatFileSize(attachment.fileSize)} • Uploaded {formatTimeAgo(attachment.uploadedAt)}
                  </div>
                </div>
                <button
                  className={styles.downloadBtn}
                  onClick={() => handleDownload(attachment.id, attachment.fileName)}
                >
                  <i className="fas fa-download"></i>
                </button>
              </div>
            );
          })
        )}
      </div>
      <div className={styles.footer}>
        <input
          ref={fileInputRef}
          type="file"
          multiple
          className={styles.fileInput}
          onChange={handleFileChange}
        />
        <Button variant="secondary" onClick={handleUploadClick}>
          <i className="fas fa-upload"></i> Upload File
        </Button>
      </div>
    </div>
  );
};

export default AttachmentsTab;
