/**
 * Helper function to get all pool tasks
 */
export const getMockPoolTasks = (): Task[] => {
  return mockPoolTasks;
};

/**
 * Helper function to get pool tasks filtered by skills
 * @param skills Array of required skills to filter
 * @returns Tasks that match at least one skill
 */
export const getMockPoolTasksBySkills = (skills: string[]): Task[] => {
  if (!skills || skills.length === 0) {
    return mockPoolTasks;
  }

  return mockPoolTasks.filter((task) =>
    task.skillsRequired.some((skill) => 
      skills.some((s) => skill.toLowerCase().includes(s.toLowerCase()))
    )
  );
};

/**
 * Helper function to get pool tasks filtered by priority
 */
export const getMockPoolTasksByPriority = (priority: TaskPriority): Task[] => {
  return mockPoolTasks.filter((task) => task.priority === priority);
};

/**
 * Helper function to get pool tasks filtered by deadline proximity
 * @param hours Number of hours from now
 * @returns Tasks due within specified hours
 */
export const getMockPoolTasksByDeadline = (hours: number): Task[] => {
  const deadlineThreshold = new Date(Date.now() + hours * 60 * 60 * 1000);
  return mockPoolTasks.filter((task) => new Date(task.dueDate) <= deadlineThreshold);
};

/**
 * Helper function to simulate claiming a task from pool
 * @param taskId Task ID to claim
 * @param userId User ID claiming the task
 * @returns Updated task with assignee info
 */
export const simulateClaimTask = (taskId: string, userId: string, userName: string): Task | null => {
  const task = mockPoolTasks.find((t) => t.id === taskId);
  if (!task) {
    return null;
  }

  // Create a claimed version of the task
  return {
    ...task,
    status: TaskStatus.Assigned,
    assigneeId: userId,
    assigneeName: userName,
    assignmentStrategy: AssignmentStrategy.Direct, // Changed from pool to direct after claiming
    updatedAt: new Date(),
  };
};

/**
 * Helper function to get pool task statistics
 */
export const getMockPoolTaskStats = () => {
  return {
    total: mockPoolTasks.length,
    critical: mockPoolTasks.filter((t) => t.priority === TaskPriority.Critical).length,
    high: mockPoolTasks.filter((t) => t.priority === TaskPriority.High).length,
    medium: mockPoolTasks.filter((t) => t.priority === TaskPriority.Medium).length,
    low: mockPoolTasks.filter((t) => t.priority === TaskPriority.Low).length,
    dueToday: mockPoolTasks.filter(
      (t) => new Date(t.dueDate).toDateString() === new Date().toDateString()
    ).length,
    dueTomorrow: mockPoolTasks.filter((t) => {
      const tomorrow = new Date();
      tomorrow.setDate(tomorrow.getDate() + 1);
      return new Date(t.dueDate).toDateString() === tomorrow.toDateString();
    }).length,
  };
};
